async function executeRoutineUpdate({
	args,
	client,
	readDataSource,
}: CommandContext) {
	requireMutationConfirmation(args);
	const input = await loadMutationInput(
		mutationData(args),
		updateRoutineInputSchema,
		readDataSource,
	);
