import { readFile } from "node:fs/promises";
import { z } from "zod";
import { UsageError } from "./arguments.js";

export type DataSourceReader = (source: string) => Promise<string>;

async function readStdin(): Promise<string> {
	const chunks: Buffer[] = [];
	for await (const chunk of process.stdin) {
		chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
	}
	return Buffer.concat(chunks).toString("utf8");
}

export const readDataSource: DataSourceReader = (source) =>
	source === "-" ? readStdin() : readFile(source, "utf8");

function schemaDiagnostic(error: z.ZodError): string {
	const issue = error.issues[0];
	const path = issue?.path.join(".");
	return path
		? `--data.${path} ${issue.message}`
		: `--data ${issue?.message ?? "is invalid"}`;
}

export async function loadMutationInput<T>(
	value: string,
	schema: z.ZodType<T>,
	reader: DataSourceReader = readDataSource,
): Promise<T> {
	let sourceValue = value;
	if (value.startsWith("@")) {
		const source = value.slice(1);
		if (source.length === 0)
			throw new UsageError("--data source is required after @");
		try {
			sourceValue = await reader(source);
		} catch {
			throw new UsageError(`Unable to read --data source "${source}"`);
		}
	}

	let parsed: unknown;
	try {
		parsed = JSON.parse(sourceValue);
	} catch {
		throw new UsageError("--data must contain valid JSON");
	}

	try {
		return schema.parse(parsed);
	} catch (error) {
		if (error instanceof z.ZodError)
			throw new UsageError(schemaDiagnostic(error));
		throw error;
	}
}

import { z } from "zod";

const numberSchema = z.number();

export type ApiValue =
	| string
	| number
	| boolean
	| null
	| undefined
	| object
	| ApiValue[];
export type ApiObject = { [key: string]: ApiValue };

export interface PaginationEnvelope<T> {
	page: number;
	page_count: number;
	[key: string]: number | T[];
}

export interface SearchResult<T> {
	query: string;
	matches: T[];
	pages_scanned: number;
	complete: boolean;
}

export interface SummaryResult {
	weeks: number;
	start_date: string;
	end_date: string;
	workout_count: number;
	total_duration_seconds: number;
	exercise_count: number;
	set_count: number;
	total_volume_kg: number;
	pages_scanned: number;
	complete: boolean;
}

export function pageEnvelope(
	data: ApiObject,
	key: string,
	items: readonly ApiValue[],
): ApiObject {
	return {
		page: numberSchema.safeParse(data.page).success ? data.page : 1,
		page_count: numberSchema.safeParse(data.page_count).success
			? data.page_count
			: 0,
		[key]: items,
	};
}

